ContextFieldMask diff_context_snapshots(const ContextSnapshot& a, const ContextSnapshot& b)
{
	ContextFieldMask changed;
	for (unsigned int i = 0; i < (unsigned int)ContextFieldID::Count; ++i)
		if (a.values[i] != b.values[i])
			changed.set(i);
	return changed;
}

void update_context_dirty_mask(Graph& graph)
{
	ContextSnapshot current;
	capture_context_snapshot(graph, current);

	// The first frame has nothing to compare against, so every field counts as
	// changed -- which makes every pass a cache miss and forces a full setup.
	// Anything else would let a pass reuse a SetupResult it never computed.
	graph.dirty_context_fields = graph.has_context_snapshot
		? diff_context_snapshots(current, graph.prev_context_snapshot)
		: ~ContextFieldMask{};

	++graph.context_frame_index;

	// Stamp the frame each changed field changed on. A pass compares its own
	// last_setup_frame against these, so a change is still visible to a pass
	// that was absent from the graph when it happened.
	for (unsigned int i = 0; i < (unsigned int)ContextFieldID::Count; ++i)
		if (graph.dirty_context_fields.test(i))
			graph.context_field_changed_frame[i] = graph.context_frame_index;

	// Whole-snapshot hash, for keying a stored graph plan. Deliberately covers
	// EVERY field, not just the ones some pass's condition reads: a plan key
	// attributes nothing, so a context only a [Size] expression touches
	// (ViewportContext) still has to move it.
	unsigned long long h = 1469598103934665603ull;
	for (unsigned int i = 0; i < (unsigned int)ContextFieldID::Count; ++i)
	{
		h ^= current.values[i];
		h *= 1099511628211ull;
	}
	graph.context_snapshot_hash = h;

	graph.prev_context_snapshot = current;
	graph.has_context_snapshot  = true;
}

